#!/usr/bin/env bash
# Compiles the Linux renderer's effect shaders (src/linux/impeller/shaders/*.frag) with the pinned
# engine's impellerc (built by tools/linux/build-impeller.sh) into Vulkan + OpenGL ES runtime
# stages, embedded as src/linux/impeller/effect_shaders.inc. Run after editing a shader; the
# generated file is committed (the SDK the builds use carries no impellerc).
set -euo pipefail
root="${IMPELLER_ROOT:-$HOME/launchme-impeller}"
out="$root/flutter/engine/src/out/launchme_impeller"
here="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)"
shaders="$here/src/linux/impeller/shaders"
target="$here/src/linux/impeller/effect_shaders.inc"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
{
    echo "// Generated by tools/linux/build-shaders.sh from src/linux/impeller/shaders: do not edit."
    for source in "$shaders"/*.frag; do
        name="$(basename "$source" .frag)"
        "$out/impellerc" --iplr --runtime-stage-vulkan --runtime-stage-gles --input="$source" --input-type=frag \
            --sl="$work/$name.iplr" --spirv="$work/$name.spv" --include="$out/shader_lib" >&2
        echo "alignas(16) constexpr unsigned char ${name}_shader[] = {"
        od -An -v -tx1 "$work/$name.iplr" | sed -E 's/ ([0-9a-f]{2})/0x\1,/g; s/^/   /'
        echo "};"
    done
} > "$target"
echo "Shaders: $target"
